<script setup lang="ts">
import { computed, defineComponent, h, ref, type PropType } from 'vue'

type Result = 'below' | 'above' | 'critical' | 'incomplete'
type Item = { number: number; label: string; response: 'YES' | 'NO'; score: number; isCritical: boolean; isYes: boolean }
type Participant = { key:string; participantId:string; name:string; email:string; displayEmail:string; timestamp:string; age:number; sex:string; gender:string; role:string; school:string; course:string; yearLevel:string; participation:string; contact:string; civilStatus:string; score:number; yesCount:number; noCount:number; answeredCount:number; totalAttempts:number; item17Yes:boolean; result:Result; resultLabel:string; recommendation:string; items:Item[] }

const questions = ['Do you often have headaches?','Is your appetite poor?','Do you sleep badly?','Are you easily frightened?','Do your hands shake?','Do you feel nervous, tense or worried?','Is your digestion poor?','Do you have trouble thinking clearly?','Do you feel unhappy?','Do you cry more than usual?','Do you find it difficult to enjoy your daily activities?','Do you find it difficult to make decisions?','Is your daily work suffering?','Are you unable to play a useful part in life?','Have you lost interest in things?','Do you feel that you are a worthless person?','Has the thought of ending your life been on your mind?','Do you feel tired all the time?','Do you have uncomfortable feelings in your stomach?','Are you easily tired?']
const seeds = [
  ['Maria Santos','Female','Youth Development Worker','Quezon City University','BS Psychology','3rd Year','Volunteer',5,false],['Juan Dela Cruz','Male','Learning Facilitator','Polytechnic University','BS Education','4th Year','Learning Facilitator',9,false],['Angela Reyes','Female','Youth Development Worker','University of Manila','BS Social Work','2nd Year','Volunteer',3,false],['Carlo Mendoza','Male','Learning Facilitator','PNU Manila','BSEd English','4th Year','Learning Facilitator',12,true],['Sofia Garcia','Female','Applicant','Pamantasan ng Lungsod ng Maynila','BA Communication','1st Year','Volunteer',7,false],['Miguel Flores','Male','Applicant','Technological University','BS Information Technology','3rd Year','Volunteer',2,false],['Bea Ramos','Female','Youth Development Worker','Philippine Normal University','BSEd Filipino','4th Year','Youth Development Worker',10,false],['Luis Bautista','Male','Applicant','Manila City College','BS Psychology','2nd Year','Volunteer',6,false],['Ana Villanueva','Female','Learning Facilitator','University of the East','BSEd Mathematics','3rd Year','Learning Facilitator',8,false],['Paolo Navarro','Male','Youth Development Worker','National Teachers College','BS Social Work','4th Year','Youth Development Worker',4,false]
] as const
function makeParticipant(seed: typeof seeds[number], index:number):Participant { const [name,sex,role,school,course,yearLevel,participation,rawScore,critical]=seed; const yesNumbers=new Set<number>(); for(let i=0;i<rawScore;i++)yesNumbers.add(((i*3+index*2)%20)+1); if(critical)yesNumbers.add(17); while(yesNumbers.size>rawScore)yesNumbers.delete([...yesNumbers].find(n=>n!==17)!); const score=yesNumbers.size; const result:Result=critical?'critical':score>=8?'above':'below'; return {key:`participant-${index+1}`,participantId:`P-${String(index+1).padStart(3,'0')}`,name,email:`${name.toLowerCase().replaceAll(' ','.')}@example.org`,displayEmail:`${name.slice(0,2).toLowerCase()}***@example.org`,timestamp:`September ${18-(index%8)}, 2026 ${9+(index%4)}:${index%2?'30':'00'} AM`,age:19+(index%6),sex,gender:sex,role,school,course,yearLevel,participation,contact:`09****${String(21+index).padStart(2,'0')}`,civilStatus:'Single',score,yesCount:score,noCount:20-score,answeredCount:20,totalAttempts:index%3===0?2:1,item17Yes:critical,result,resultLabel:critical?'Item 17 flagged':score>=8?'Above selected cut-off':'Below selected cut-off',recommendation:critical?'Immediate confidential safety review according to the approved referral protocol.':score>=8?'Confidential follow-up and further assessment recommended.':'No elevated screen based on the selected cut-off. Continue appropriate monitoring.',items:questions.map((label,i)=>({number:i+1,label,response:yesNumbers.has(i+1)?'YES':'NO',score:yesNumbers.has(i+1)?1:0,isCritical:i+1===17,isYes:yesNumbers.has(i+1)}))} }

const participants=ref<Participant[]>(seeds.map(makeParticipant)), authorized=ref(sessionStorage.getItem('srq20-authorized')==='true'), accessEmail=ref(''), accessError=ref(''), view=ref<'summary'|'participants'|'individual'>('summary'), selected=ref<Participant|null>(participants.value[0]??null), search=ref(''), sex=ref(''), role=ref(''), result=ref<Result|''>('')
const sexes=computed(()=>[...new Set(participants.value.map(p=>p.sex))].sort()), roles=computed(()=>[...new Set(participants.value.map(p=>p.role))].sort())
const filtered=computed(()=>participants.value.filter(p=>{const text=`${p.name} ${p.email} ${p.role} ${p.school}`.toLowerCase();return(!search.value||text.includes(search.value.toLowerCase()))&&(!sex.value||p.sex===sex.value)&&(!role.value||p.role===role.value)&&(!result.value||p.result===result.value)}))
const summary=computed(()=>{const rows=filtered.value;return{total:rows.length,average:rows.length?(rows.reduce((n,p)=>n+p.score,0)/rows.length).toFixed(1):'—',above:rows.filter(p=>p.result==='above').length,below:rows.filter(p=>p.result==='below').length,critical:rows.filter(p=>p.result==='critical').length}})
function countBy<T>(list:T[],key:(item:T)=>string){return Object.entries(list.reduce<Record<string,number>>((a,x)=>{const k=key(x);a[k]=(a[k]||0)+1;return a},{})).map(([label,value])=>({label,value}))}
const sexCounts=computed(()=>countBy(filtered.value,p=>p.sex)), participationCounts=computed(()=>countBy(filtered.value,p=>p.participation)), ageCounts=computed(()=>countBy(filtered.value,p=>String(p.age))), itemCounts=computed(()=>questions.map((label,i)=>({label,number:i+1,value:filtered.value.filter(p=>p.items[i]?.isYes).length}))), scoreCounts=computed(()=>Array.from({length:21},(_,score)=>({label:String(score),value:filtered.value.filter(p=>p.score===score).length})))
function enterDashboard(){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(accessEmail.value.trim())){accessError.value='Please enter a valid email address.';return}const logs=JSON.parse(localStorage.getItem('srq20-access-log')||'[]');logs.push({timestamp:new Date().toISOString(),email:accessEmail.value.trim().toLowerCase(),action:'Dashboard opened'});localStorage.setItem('srq20-access-log',JSON.stringify(logs));sessionStorage.setItem('srq20-authorized','true');authorized.value=true}
function openParticipant(p:Participant){selected.value=p;view.value='individual'} function filterResult(v:Result){result.value=v;view.value='participants'} function resetFilters(){search.value='';sex.value='';role.value='';result.value=''} function badgeClass(v:Result){return v==='critical'?'red':v==='above'?'orange':v==='below'?'green':'gray'} function initials(name:string){return name.split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase()}
function downloadCsv(){const headers=['Participant ID','Participant Name','Email','Sex','Age','Role','School','Course','Year Level','Participation','YES Count','NO Count','Score','Result','Item 17','Timestamp'];const cell=(v:unknown)=>`"${String(v??'').replaceAll('"','""')}"`;const rows=filtered.value.map(p=>[p.participantId,p.name,p.displayEmail,p.sex,p.age,p.role,p.school,p.course,p.yearLevel,p.participation,p.yesCount,p.noCount,p.score,p.resultLabel,p.item17Yes?'YES':'NO',p.timestamp]);const blob=new Blob([[headers,...rows].map(r=>r.map(cell).join(',')).join('\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='SRQ20_participant_report.csv';a.click();URL.revokeObjectURL(a.href)}
function printPage(){window.print()}
const ParticipantTable=defineComponent({props:{items:{type:Array as PropType<Participant[]>,required:true}},emits:['open'],setup(props,{emit}){return()=>h('div',{class:'table-wrap'},[h('table',[h('thead',[h('tr',['Participant','Age','Sex','Participation','YES','NO','Score','Item 17','Result','Response status'].map(x=>h('th',x)))]),h('tbody',props.items.map(p=>h('tr',{onClick:()=>emit('open',p)},[h('td',[h('strong',p.name),h('br'),h('span',{class:'muted'},p.displayEmail)]),h('td',`${p.age} yrs`),h('td',p.sex),h('td',p.participation),h('td',[h('span',{class:'badge orange'},String(p.yesCount))]),h('td',[h('span',{class:'badge green'},String(p.noCount))]),h('td',`${p.score}/20`),h('td',[h('span',{class:`badge ${p.item17Yes?'red':'green'}`},p.item17Yes?'YES':'NO')]),h('td',[h('span',{class:`badge ${p.result==='critical'?'red':p.result==='above'?'orange':'green'}`},p.resultLabel)]),h('td',`${p.answeredCount}/20 answered`)])))])])}})
</script>

<template>
<section v-if="!authorized" class="confidential-page"><div class="confidential-card"><div class="confidential-label">Restricted access · Highly confidential</div><h1>SRQ-20 Participant Evaluation Dashboard</h1><p>This dashboard contains sensitive personal information and self-reported mental health screening responses. Access and use are limited to authorized personnel with a legitimate program-related purpose.</p><h2>Confidentiality and responsible use</h2><ul><li>Use the information only for approved screening, monitoring, referral, and program support activities.</li><li>Do not share, screenshot, download, or reproduce individual results unless authorized.</li><li>Protect participant names, contact details, demographics, and SRQ-20 responses.</li><li>SRQ-20 results are screening indicators only and are not a clinical diagnosis.</li><li>Any Item 17 flag must follow the approved safety and referral protocol.</li></ul><div class="confidential-warning"><strong>Important:</strong> Your email address will be recorded locally with the date and time of access. This is an access record only and does not authenticate ownership.</div><div class="access-form"><label for="access-email">Enter your email address</label><input id="access-email" v-model="accessEmail" type="email" placeholder="name@example.com" @keyup.enter="enterDashboard"><div class="access-note">Any valid email address may be used for this standalone version.</div><div class="access-error">{{accessError}}</div></div><div class="confidential-actions"><button class="button" @click="enterDashboard">Record Email and Continue</button></div></div></section>
<div v-else class="app"><aside class="sidebar"><div class="brand"><div class="brand-mark">S</div><div><div class="brand-title">SRQ-20 Dashboard</div><div class="brand-subtitle">Tara, Usap! Applications</div></div></div><nav class="nav"><button :class="{active:view==='summary'}" @click="view='summary'">▦ &nbsp; Summary</button><button :class="{active:view==='participants'}" @click="view='participants'">☷ &nbsp; Participants</button><button :class="{active:view==='individual'}" @click="view='individual'">◉ &nbsp; Individual Evaluation</button></nav><div class="sidebar-note">Source: <strong>Standalone demo dataset</strong><br><br>Score: YES = 1, NO = 0. Selected cut-off: 8/20.</div></aside>
<main class="main"><header class="topbar"><div class="crumb"><strong>Call for Application</strong> / {{view==='summary'?'Summary':view==='participants'?'Participants':'Individual Evaluation'}}</div><div class="top-actions"><select v-model="sex" class="select"><option value="">All sex categories</option><option v-for="s in sexes" :key="s">{{s}}</option></select><select v-model="role" class="select"><option value="">All roles</option><option v-for="r in roles" :key="r">{{r}}</option></select><select v-model="result" class="select"><option value="">All results</option><option value="below">Below selected cut-off</option><option value="above">Above selected cut-off</option><option value="critical">Item 17 flagged</option><option value="incomplete">Incomplete response</option></select><div class="avatar">AR</div></div></header>
<section class="dashboard-banner"><div><div class="banner-kicker">Tara, Usap! Applications</div><h1>SRQ-20 Participant Evaluation Dashboard</h1><p>Self-Reporting Questionnaire summary, participant search, and individual evaluation results</p></div><div class="banner-score">YES = 1 · NO = 0 · MAX = 20</div></section>
<div class="content"><section v-if="view==='summary'" class="view"><div class="page-head"><div><h1>SRQ-20 Assessment Summary</h1><p class="sub">Individual screening results from the Tara, Usap! application form.</p></div><div class="export-actions"><button class="button alt" @click="view='participants'">View participants</button><button class="button alt" @click="downloadCsv">Download CSV</button><button class="button" @click="printPage">Print report</button></div></div>
<div class="cards"><div class="card"><span>Unique participants</span><strong>{{summary.total}}</strong><small>Filtered participant records</small></div><div class="card"><span>Average score</span><strong>{{summary.average}}</strong><small>Out of 20 points</small></div><div class="card"><span>Above cut-off</span><strong>{{summary.above}}</strong><small class="orange">Follow-up recommended</small></div><div class="card"><span>Item 17 flagged</span><strong>{{summary.critical}}</strong><small class="red">Immediate confidential review</small></div></div>
<div class="grid-two"><div class="panel"><div class="panel-head"><div><h2>Score interpretation</h2><p class="sub">Based on complete responses only</p></div></div><button v-for="row in [{key:'below',label:'Below selected cut-off',value:summary.below,color:'var(--primary)'},{key:'above',label:'Above selected cut-off',value:summary.above,color:'var(--accent)'},{key:'critical',label:'Item 17 flagged',value:summary.critical,color:'var(--red)'}]" :key="row.key" class="interpretation" @click="filterResult(row.key as Result)"><span>{{row.label}}</span><i><b :style="{width:(row.value/Math.max(1,summary.total)*100)+'%',background:row.color}"></b></i><strong>{{row.value}}</strong></button></div><div class="panel"><div class="panel-head"><div><h2>Participants by sex</h2><p class="sub">Unique participants</p></div></div><div class="bar-list"><div v-for="row in sexCounts" :key="row.label" class="bar"><span>{{row.label}}</span><i><b :style="{width:(row.value/Math.max(1,summary.total)*100)+'%'}"></b></i><strong>{{row.value}}</strong></div></div></div></div>
<div class="grid-two spaced"><div class="panel"><div class="panel-head"><div><h2>Total answered YES and NO</h2><p class="sub">Latest evaluation of each participant</p></div></div><div class="bar-list"><div v-for="row in [{label:'YES',value:filtered.reduce((n,p)=>n+p.yesCount,0)},{label:'NO',value:filtered.reduce((n,p)=>n+p.noCount,0)}]" :key="row.label" class="bar"><span>{{row.label}}</span><i><b :style="{width:(row.value/Math.max(1,filtered.length*20)*100)+'%'}"></b></i><strong>{{row.value}}</strong></div></div></div><div class="panel"><div class="panel-head"><div><h2>Participation preference</h2><p class="sub">How participants would like to participate</p></div></div><div class="bar-list"><div v-for="row in participationCounts" :key="row.label" class="bar"><span>{{row.label}}</span><i><b :style="{width:(row.value/Math.max(1,summary.total)*100)+'%'}"></b></i><strong>{{row.value}}</strong></div></div></div></div>
<div class="grid-two spaced"><div class="panel"><div class="panel-head"><div><h2>Participants by age</h2><p class="sub">Number of unique participants by age</p></div></div><div class="columns"><div v-for="row in ageCounts" :key="row.label"><span>{{row.value}}</span><i :style="{height:(row.value/Math.max(...ageCounts.map(x=>x.value),1)*150)+'px'}"></i><small>{{row.label}}</small></div></div></div><div class="panel"><div class="panel-head"><div><h2>Score distribution</h2><p class="sub">Filtered participants</p></div></div><div class="columns compact"><div v-for="row in scoreCounts" :key="row.label"><span>{{row.value||''}}</span><i :style="{height:(row.value/Math.max(...scoreCounts.map(x=>x.value),1)*150)+'px'}"></i><small>{{row.label}}</small></div></div></div></div>
<div class="panel spaced"><div class="panel-head"><div><h2>Most reported symptoms</h2><p class="sub">Number of YES responses per SRQ-20 item</p></div></div><div class="item-bars"><div v-for="row in itemCounts" :key="row.number"><span>{{row.number}}. {{row.label}}</span><i><b :style="{width:(row.value/Math.max(1,summary.total)*100)+'%'}"></b></i><strong>{{row.value}}</strong></div></div></div><div class="panel spaced"><div class="panel-head"><div><h2>Participant records</h2><p class="sub">Click a row to open the individual evaluation.</p></div></div><ParticipantTable :items="filtered.slice(0,8)" @open="openParticipant" /></div></section>
<section v-else-if="view==='participants'" class="view"><div class="page-head"><div><h1>Participants</h1><p class="sub">Search and review each participant's SRQ-20 evaluation.</p></div><div class="export-actions"><button class="button alt" @click="view='summary'">Back to summary</button><button class="button alt" @click="resetFilters">Clear filters</button><button class="button" @click="downloadCsv">Download CSV</button></div></div><div class="panel"><div class="toolbar"><div><h2>Participant records</h2><p class="sub">Filters apply to search, sex, role, and result.</p></div><input v-model="search" class="search" placeholder="Search name, email, role, or school"></div><ParticipantTable :items="filtered" @open="openParticipant" /></div></section>
<section v-else class="view individual-view"><div class="page-head"><div><h1>Individual Evaluation</h1><p class="sub">Detailed SRQ-20 evaluation and participant information.</p></div><div class="export-actions"><button class="button alt" @click="view='participants'">Participant list</button><button class="button" @click="printPage">Print / Save PDF</button></div></div><div v-if="selected" class="panel"><div class="profile"><div class="profile-main"><div class="profile-avatar">{{initials(selected.name)}}</div><div><h2>{{selected.name}}</h2><p>{{selected.displayEmail}} · {{selected.timestamp}}</p></div></div><span class="badge" :class="badgeClass(selected.result)">{{selected.resultLabel}}</span></div><div class="individual-grid"><div><div class="panel nested"><div class="score-box"><div class="score-circle" :style="{background:`conic-gradient(${selected.item17Yes?'var(--red)':'var(--primary)'} 0 ${selected.score*5}%,#e8edf5 ${selected.score*5}% 100%)`}"><div><strong>{{selected.score}}</strong><span>out of 20</span></div></div><div><h2>{{selected.resultLabel}}</h2><p class="result-copy">YES responses receive 1 point and NO responses receive 0 points. The score is a screening result, not a diagnosis.</p><span class="badge" :class="badgeClass(selected.result)">{{selected.recommendation}}</span></div></div><div class="detail-grid"><div><span>Answered items</span><strong>{{selected.answeredCount}}/20</strong></div><div><span>Attempts</span><strong>{{selected.totalAttempts}}</strong></div><div><span>Cut-off</span><strong>8/20</strong></div><div><span>Item 17</span><strong :class="selected.item17Yes?'danger':'safe'">{{selected.item17Yes?'YES':'NO'}}</strong></div></div></div><div class="panel nested spaced"><h2>Participant information</h2><table class="profile-table"><tbody><tr v-for="field in [['Participant ID',selected.participantId],['Age',selected.age+' years'],['Sex',selected.sex],['Gender',selected.gender],['Civil status',selected.civilStatus],['Contact',selected.contact],['School',selected.school],['Program / Course',selected.course],['Year level',selected.yearLevel],['Current role',selected.role],['Participation',selected.participation]]" :key="String(field[0])"><td>{{field[0]}}</td><td><strong>{{field[1]}}</strong></td></tr></tbody></table></div></div><div class="panel nested"><div class="panel-head"><div><h2>Item-by-item responses</h2><p class="sub">SRQ-20 questions answered in the form</p></div></div><div class="question-list"><div v-for="item in selected.items" :key="item.number" class="question-row" :class="{'critical-row':item.isCritical&&item.isYes}"><span>{{item.number}}. {{item.label}}</span><strong :class="item.isYes?'answer-yes':'answer-no'">{{item.response}}</strong><em>{{item.score}} pt</em></div></div><div v-if="selected.item17Yes" class="critical-note"><strong>!</strong><span>Item 17 was answered YES. Follow the approved confidential safety and referral procedure immediately.</span></div></div></div></div></section></div></main></div>
</template>
